"""Synthetic archive boundary fixtures; no generated bytes are Android/UI evidence."""
import contextlib
import copy
import hashlib
import io
import json
from pathlib import Path
import tempfile
import unittest
from unittest import mock

import probe_video_archive as archive
import test_pinned_page_archive as page_fixture
import test_third_party_smoke_set as app_fixture

SOURCE = app_fixture.SOURCE
VIDEO = b'synthetic parser fixture, not a video'


def write(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value) + '\n')


def source_run(profile='third-party-app-set'):
    run = app_fixture.source_run()
    if profile == 'pinned-calculator-page':
        run['path'] = '.github/workflows/pinned-calculator-page.yml'
    return run


def job(profile='third-party-app-set'):
    return {'id': 700, 'name': 'probe (35)' if profile == 'third-party-app-set' else 'page-predicate (35)',
        'status': 'completed', 'run_id': 123, 'run_attempt': 2, 'head_sha': 'a' * 40, 'conclusion': 'success',
        'started_at': '2026-10-27T09:01:00Z', 'completed_at': '2026-10-27T09:09:00Z'}


def artifacts(profile='third-party-app-set'):
    probe = app_fixture.artifact('35')
    if profile == 'pinned-calculator-page':
        probe['name'] = 'screenshots-api-35-attempt-2'
    video = copy.deepcopy(probe)
    video.update(id=900, name=f'probe-video-{profile}-api-35-attempt-2')
    return [probe, video]


def recording(profile, failed=False, raw=False):
    metadata = {'bytes': len(VIDEO), 'sha256': hashlib.sha256(VIDEO).hexdigest(),
                'durationMs': 3000, 'width': 320, 'height': 640, 'codec': 'h264', 'pixelFormat': 'yuv420p'}
    value = {'schemaVersion': 1, 'kind': 'agent-os-probe-video', 'source': SOURCE, 'profile': profile,
        'apiLevel': 35, 'status': 'passed', 'recordingStatus': 'recorded', 'callbackOutcome': 'returned',
        'callbackErrorClass': None, 'callbackElapsedMs': 2000, 'callbackStartedAfterRecorderMs': 400,
        'callbackFinishedAfterRecorderMs': 2400, 'timeLimitSeconds': 120, 'secureFlagsPreserved': True,
        'testOutcomeIndependent': True, 'coverage': {'status': 'covered', 'recorderAliveBeforeCallback': True,
            'recorderAliveAfterCallback': True, 'durationToleranceMs': 1500},
        'rawVideo': copy.deepcopy(metadata), 'rawRetained': False, 'video': metadata,
        'recorder': {'started': True, 'exitCode': 0, 'stderr': {'text': '', 'truncated': False, 'complete': True}},
        'failures': [], 'probes': [{'stage': stage, 'status': 'completed', 'exitCode': 0,
            'stdout': 'synthetic metadata parser fixture'} for stage in ('raw_probe', 'encoded_probe')]}
    if failed:
        value.update(status='failed', callbackElapsedMs=600000, callbackFinishedAfterRecorderMs=600400,
                     failures=[{'stage': 'coverage', 'errorClass': None}])
        value['coverage'].update(status='incomplete', recorderAliveAfterCallback=False)
    if raw:
        value.update(status='failed', recordingStatus='unavailable', video=None, rawRetained=True,
            rawVideo={key: metadata[key] for key in ('bytes', 'sha256')},
            failures=[{'stage': 'video_encode', 'errorClass': 'ValueError'}])
        value['coverage']['status'] = 'unavailable'
    return value


def instrumentation(states):
    blocks = []
    failed = 0
    for (app, state), method in archive.APPSET_METHODS.items():
        status = states[app][state]
        failed += status == 'failed'
        for code in (1, 0 if status == 'passed' else -2):
            blocks.extend([f'INSTRUMENTATION_STATUS: class={archive.APPSET_CLASS}',
                'INSTRUMENTATION_STATUS: numtests=4', f'INSTRUMENTATION_STATUS: test={method}',
                f'INSTRUMENTATION_STATUS_CODE: {code}'])
    blocks.extend(['FAILURES!!!\nTests run: 4, Failures: ' + str(failed) if failed else 'OK (4 tests)', 'INSTRUMENTATION_CODE: -1'])
    return {'commandCompleted': True, 'output': '\n'.join(blocks) + '\n'}


class ProbeVideoArchive(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.incoming = self.root / 'incoming'
        self.incoming.mkdir()
        self.profile = 'third-party-app-set'
        self.run = source_run()
        self.jobs = {'jobs': [job()]}
        self.index = {'artifacts': artifacts()}
        self.decode = self.enterContext(mock.patch.object(archive.demo_video.bounded, 'run_command', return_value=''))
        self.enterContext(mock.patch.object(archive.demo_video, 'video_metadata', side_effect=lambda path, encoded:
            json.loads((Path(path).parent / 'recording.json').read_text())['video']))

    def prepare(self, profile='third-party-app-set', video_failed=False, raw=False):
        self.profile = profile
        self.run, self.jobs, self.index = source_run(profile), {'jobs': [job(profile)]}, {'artifacts': artifacts(profile)}
        if profile == 'pinned-calculator-page':
            folder = page_fixture.write_lane(self.root, '35')
        else:
            folder = self.incoming / artifacts(profile)[0]['name']
            lock = archive.appset.load_lock()
            report = app_fixture.report(lock, '35', captures=False)
            report['verifiedDownloads'] = {item['appId']: {k: item['app'][k] for k in ('package', 'versionCode',
                'versionName', 'minSdk', 'targetSdk', 'abis', 'certificateSha256', 'sha256')} for item in lock['apps']}
            names = ('device_preflight', 'apk_verification_calculator-1.4.0', 'apk_verification_notes-1.7.0',
                'fresh_install_precondition', 'install_agent', 'install_calculator', 'install_notes',
                'install_probe', 'install_probe_tests', 'instrumentation', 'collect_ui_results')
            report['driverSteps'] = [{'name': name, 'status': 'passed'} for name in names]
            for step in report['driverSteps']:
                if step['name'].startswith('install_'): step['sha256'] = 'b' * 64
                if step['name'] == 'install_calculator': step['sha256'] = lock['apps'][0]['app']['sha256']
                if step['name'] == 'install_notes': step['sha256'] = lock['apps'][1]['app']['sha256']
            ui = app_fixture.ui_from_report(lock, report)
            write(folder / 'ui-results.json', ui)
            report['uiResultsSha256'] = hashlib.sha256((folder / 'ui-results.json').read_bytes()).hexdigest()
            write(folder / 'report.json', report)
            write(folder / 'instrumentation.json', instrumentation({app: {state: 'passed' for state in ('off', 'idle')}
                                                                    for app in archive.appset.APP_IDS}))
        video = self.incoming / artifacts(profile)[1]['name']
        value = recording(profile, video_failed, raw)
        write(video / 'recording.json', value)
        (video / ('raw.mp4' if raw else 'demo.mp4')).write_bytes(VIDEO)
        return folder, video

    def execute(self):
        return archive.archive(self.run, self.jobs, self.index, self.incoming, self.root)

    def reject(self, message):
        with self.assertRaisesRegex(ValueError, message): self.execute()
        self.assertFalse((self.root / 'screenshots/demos/probes-123-2').exists())

    def test_archive_keeps_video_original_bytes_and_fixed_four_case_scope(self):
        folder, video = self.prepare()
        before = (folder / 'report.json').read_bytes()
        result = self.execute()
        self.assertEqual(('passed', 'passed', 'passed'), (result['status'], result['recordingStatus'], result['probeStatus']))
        self.assertEqual({'passed': 4, 'failed': 0, 'unverified': 0}, result['caseCounts'])
        self.assertEqual((4, 32, False), (result['expectedTests'], result['matrixExpectedTests'], result['fullSuiteAcceptance']))
        destination = self.root / 'screenshots/demos/probes-123-2'
        self.assertEqual(before, (destination / 'probe/report.json').read_bytes())
        self.assertEqual(VIDEO, (destination / 'video/demo.mp4').read_bytes())
        self.assertEqual({f['path'] for f in result['files']}, {p.relative_to(destination).as_posix()
            for p in destination.rglob('*') if p.is_file()} - {'manifest.json'})
        self.decode.assert_called_once()

    def test_production_page_profile_has_five_cases_not_twenty_or_internal_visual_scope(self):
        self.prepare('pinned-calculator-page')
        result = self.execute()
        self.assertEqual(('passed', 5, 20), (result['status'], result['expectedTests'], result['matrixExpectedTests']))
        self.assertEqual(5, result['caseCounts']['passed'])
        self.assertFalse(result['fullSuiteAcceptance'])

    def test_recording_failure_preserves_passed_probe_and_actual_partial_video(self):
        self.prepare(video_failed=True)
        result = self.execute()
        self.assertEqual(('failed', 'failed', 'passed'), (result['status'], result['recordingStatus'], result['probeStatus']))
        self.assertEqual('video/demo.mp4', result['videoPath'])

    def test_encoding_failure_keeps_raw_digest_without_calling_it_a_valid_video(self):
        self.prepare(raw=True)
        result = self.execute()
        self.assertIsNone(result['videoPath'])
        self.assertEqual('failed', result['status'])
        self.assertTrue((self.root / 'screenshots/demos/probes-123-2/video/raw.mp4').is_file())
        self.decode.assert_not_called()

    def test_other_api_failures_do_not_relabel_api35_as_failed(self):
        self.prepare()
        self.run['conclusion'] = 'failure'
        result = self.execute()
        self.assertEqual(('passed', 'failure'), (result['status'], result['sourceRunConclusion']))
        self.assertFalse(result['fullSuiteAcceptance'])

    def test_failed_api35_job_cannot_promote_successful_receipts(self):
        self.prepare()
        self.run['conclusion'] = self.jobs['jobs'][0]['conclusion'] = 'failure'
        self.assertEqual('failed', self.execute()['status'])

    def test_missing_and_expired_artifacts_keep_all_unverified_cases(self):
        self.index['artifacts'][0]['expired'] = True
        self.index['artifacts'].pop()
        result = self.execute()
        self.assertEqual({'passed': 0, 'failed': 0, 'unverified': 4}, result['caseCounts'])
        self.assertEqual(('expired', 'unavailable'), (result['artifacts']['probe']['status'], result['artifacts']['video']['status']))
        self.assertEqual('failed', result['status'])

    def test_source_fork_workflow_and_attempt_tampering_are_rejected(self):
        mutations = (lambda r: r['head_repository'].update(id=999), lambda r: r.update(event='push'),
            lambda r: r.update(head_branch='feature'), lambda r: r.update(path='.github/workflows/pinned-window-disclosure.yml'),
            lambda r: r.update(status='in_progress'), lambda r: r.update(run_attempt=True))
        for change in mutations:
            with self.subTest(change=change):
                value = source_run(); change(value)
                with self.assertRaises(ValueError): archive.select(value, self.jobs, self.index)

    def test_artifact_origin_job_times_duplicates_and_wrong_video_profile_are_rejected(self):
        for change in (lambda a: a['workflow_run'].update(head_sha='b' * 40),
                       lambda a: a.update(created_at='2026-10-27T09:00:01Z'),
                       lambda a: a.update(expired=None), lambda a: a.update(size_in_bytes=True)):
            current = copy.deepcopy(self.index); change(current['artifacts'][1])
            with self.assertRaises(ValueError): archive.select(self.run, self.jobs, current)
        with self.assertRaisesRegex(ValueError, 'Duplicate'):
            archive.select(self.run, self.jobs, {'artifacts': self.index['artifacts'] * 2})
        current = copy.deepcopy(self.index)
        current['artifacts'][1]['name'] = 'probe-video-pinned-calculator-page-api-35-attempt-2'
        with self.assertRaisesRegex(ValueError, 'Foreign profile'):
            archive.select(self.run, self.jobs, current)
        for key, value in (('run_attempt', 1), ('head_sha', 'b' * 40), ('name', 'probe (34)')):
            current = copy.deepcopy(self.jobs); current['jobs'][0][key] = value
            with self.assertRaises(ValueError): archive.select(self.run, current, self.index)

    def test_video_digest_and_extra_payload_are_rejected(self):
        _, video = self.prepare()
        (video / 'demo.mp4').write_bytes(VIDEO + b'changed')
        self.reject('digest differs')
        (video / 'demo.mp4').write_bytes(VIDEO)
        (video / 'extra.json').write_text('{}')
        self.reject('Unexpected video')

    def test_extra_original_probe_file_and_extra_downloaded_artifact_are_rejected(self):
        folder, _ = self.prepare()
        (folder / 'extra.json').write_text('{}')
        self.reject('Unexpected app-set')
        (folder / 'extra.json').unlink()
        (self.incoming / 'foreign').mkdir()
        self.reject('Downloaded artifact set')

    def test_ui_digest_mismatch_is_rejected(self):
        folder, _ = self.prepare()
        (folder / 'ui-results.json').write_bytes((folder / 'ui-results.json').read_bytes() + b' ')
        self.reject('UI manifest digest')

    def test_passed_probe_cannot_hide_failed_original_instrumentation(self):
        folder, _ = self.prepare()
        value = json.loads((folder / 'instrumentation.json').read_text())
        value['output'] += '\nINSTRUMENTATION_FAILED: Process crashed\n'
        write(folder / 'instrumentation.json', value)
        self.reject('summary contradicts')

    def test_passed_probe_needs_exact_four_methods(self):
        folder, _ = self.prepare()
        value = json.loads((folder / 'instrumentation.json').read_text())
        value['output'] = value['output'].replace('notesWithAgentDisabled', 'foreignMethod')
        write(folder / 'instrumentation.json', value)
        self.reject('Foreign app-set instrumentation')

    def test_before_class_failure_preserves_four_unverified_business_cases(self):
        folder, _ = self.prepare()
        lock = archive.appset.load_lock()
        value = app_fixture.report(lock, '35', passed=False)
        value.update(status='failed', device={'apiLevel': 35, 'serial': 'emulator-5554', 'abi': 'x86_64'})
        write(folder / 'ui-results.json', app_fixture.ui_from_report(lock, value))
        value['uiResultsSha256'] = hashlib.sha256((folder / 'ui-results.json').read_bytes()).hexdigest()
        write(folder / 'report.json', value)
        write(folder / 'instrumentation.json', {'commandCompleted': True, 'output':
            'INSTRUMENTATION_STATUS: class=' + archive.APPSET_CLASS + '\n'
            'INSTRUMENTATION_STATUS: test=initializationError\nINSTRUMENTATION_STATUS: numtests=1\n'
            'INSTRUMENTATION_STATUS_CODE: -2\nINSTRUMENTATION_CODE: -1\n'})
        result = self.execute()
        self.assertEqual({'passed': 0, 'failed': 0, 'unverified': 4}, result['caseCounts'])
        self.assertEqual(('failed', 'unverified'), (result['status'], result['probeStatus']))
        self.assertEqual(1, len(result['probe']['instrumentation']['setupDiagnosticBlocks']))

    def test_passed_probe_needs_all_five_install_receipts_and_frozen_signature(self):
        folder, _ = self.prepare()
        value = json.loads((folder / 'report.json').read_text())
        original = copy.deepcopy(value)
        value['driverSteps'] = [s for s in value['driverSteps'] if s['name'] != 'install_notes']
        write(folder / 'report.json', value)
        self.reject('passed driver receipt')
        value = copy.deepcopy(original)
        value['verifiedDownloads']['notes-1.7.0']['certificateSha256'] = '0' * 64
        write(folder / 'report.json', value)
        self.reject('Downloaded APK receipt')

    def test_incomplete_recording_cannot_claim_covered_success(self):
        _, video = self.prepare()
        value = json.loads((video / 'recording.json').read_text())
        value['callbackElapsedMs'] = 10000; value['callbackFinishedAfterRecorderMs'] = 10400
        write(video / 'recording.json', value)
        self.reject('coverage does not match')

    def test_video_decode_failure_prevents_archive_and_existing_output_is_preserved(self):
        self.prepare()
        self.decode.side_effect = ValueError('decode failed')
        self.reject('decode failed')
        self.decode.side_effect = None
        self.execute()
        self.reject_existing()

    def reject_existing(self):
        path = self.root / 'screenshots/demos/probes-123-2/manifest.json'
        before = path.read_bytes()
        with self.assertRaisesRegex(ValueError, 'already exists'): self.execute()
        self.assertEqual(before, path.read_bytes())

    def test_select_cli_writes_exact_checkout_and_artifact_outputs(self):
        for name, value in (('run', self.run), ('jobs', self.jobs), ('artifacts', self.index)):
            write(self.root / (name + '.json'), value)
        output = self.root / 'github-output'
        with contextlib.redirect_stdout(io.StringIO()):
            code = archive.main(['select', '--run', str(self.root / 'run.json'), '--jobs', str(self.root / 'jobs.json'),
                '--artifacts', str(self.root / 'artifacts.json'), '--github-output', str(output)])
        self.assertEqual(0, code)
        values = dict(line.split('=', 1) for line in output.read_text().splitlines())
        self.assertEqual(('123', '2', 'a' * 40, 'third-party-app-set', '235,900', 'screenshots/demos/probes-123-2'),
            tuple(values[k] for k in ('source_run', 'attempt', 'source_sha', 'profile', 'artifact_ids', 'evidence_path')))


if __name__ == '__main__':
    unittest.main()
